select * from jsonb_populate_recordset(null::public.temples, $rtam$[{"id":"87efeb05-fa1c-4a1a-a74a-aa382f7e4e14","name":"Alarnatha Mandira","deity":"Vishnu as Alarnatha, with Mahalakshmi","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Odisha","district":"Puri","town":"Brahmagiri","latitude":19.79488,"longitude":85.6502,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Bhargabi River","river_distance_km":3.4,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Vishnu temple at Brahmagiri, about 23 km from Puri, with a shrine to his consort Mahalakshmi. During the Anasara period after Snana Yatra, when Jagannath cannot be seen at Puri, devotees believe he appears here as Alarnath and visit instead. It is counted among the 108 Abhimana Kshetrams.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Biju Patnaik International Airport","nearest_airport_distance_km":53.6,"nearest_railway_station_name":"Puri railway station","nearest_railway_distance_km":19.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Alarnatha Mandira), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"8843218f-4053-46df-a836-b97ada85a9ea","name":"Ranganathaswamy Temple, Shivanasamudra","deity":"Ranganatha (Madhya Ranga)","sampradaya":"Vaishnava","significance":["Pancharanga Kshetram"],"country":"India","state":"Karnataka","district":"Chamarajanagar","town":"Shivanasamudra","latitude":12.270556,"longitude":77.169722,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kaveri","river_distance_km":0.1,"best_season_notes":"Oct–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-05T10:54:38.493897+00:00","updated_at":"2026-11-04T12:15:35.665826+00:00","sthala_purana":"The second of the five Pancharanga Kshetrams on the Kaveri, known as Madhya Ranga (\"the middle Ranga\") for its position between Srirangapatna (Adi Ranga) and Srirangam (Antya Ranga). Ranganatha here is worshipped in his youthful form, and is affectionately called Mohana Ranga or Jaganmohana Ranga. Like its counterparts, the temple stands on an island formed by the Kaveri, and forms part of the single-day Tri Ranga Darshana pilgrimage across all three Karnataka-to-Tamil Nadu Ranga shrines.","etiquette_notes":null,"native_name":"ಶ್ರೀ ರಂಗನಾಥಸ್ವಾಮಿ ದೇವಸ್ಥಾನ","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Mysore Mandakalli Airport","nearest_airport_distance_km":56.5,"nearest_railway_station_name":"Hanakere railway station","nearest_railway_distance_km":38.7,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":"Dravidian","construction_century":null},{"id":"8859fcb1-857b-4734-9d0e-8120f7038d50","name":"ISKCON Sri Krishna Balaram Mandir, Vrindavan","deity":"Krishna and Balarama (central altar); Radha Shyamsundar with the gopis Lalita and Vishakha (right altar); Chaitanya Mahaprabhu with Nityananda, alongside images of Prabhupada and his guru Bhaktisiddhanta Saraswati (left altar)","sampradaya":"Vaishnava","significance":["ISKCON temple","Houses Srila Prabhupada's samadhi"],"country":"India","state":"Uttar Pradesh","district":"Mathura","town":"Vrindavan","latitude":27.57242,"longitude":77.67775,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Yamuna River","river_distance_km":1.4,"best_season_notes":"Janmashtami, Radhashtami, Balarama Purnima, Gaura Purnima and Kartik Purnima are among the major festivals observed, alongside the appearance and disappearance days of Vaishnava acharyas.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T10:01:49.265512+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Founded by A. C. Bhaktivedanta Swami Prabhupada, who installed the deities on Ram Navami (20 April) 1975; temple construction was completed in 1977. A white-marble samadhi mandir — a memorial shrine for Prabhupada — stands near the temple entrance within the complex.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Per third-party guides, not independently confirmed against the official schedule: darshan roughly 4:30am–1pm and 4–8:15pm, with a midday closure for deity rest and prasadam preparation. Mangala Aarti at 4:30am; timings shift on Ekadashi and festival days.","accessibility_notes":null,"nearest_airport_name":"Agra (Kheria) Airport","nearest_airport_distance_km":55,"nearest_railway_station_name":"Mathura Junction","nearest_railway_distance_km":14,"emergency_contact_notes":null,"sthala_purana_source":"ISKCON institutional records","architecture_style":"Modern Hindu temple architecture, a three-shrine complex completed in 1977","construction_century":20},{"id":"885c9591-b5e4-497d-92b9-41033b174b67","name":"Attukal Bhagavathy Temple","deity":"Attukal Bhagavathy (Devi)","sampradaya":"Shakta","significance":[],"country":"India","state":"Kerala","district":"Thiruvananthapuram","town":"Thiruvananthapuram","latitude":8.474,"longitude":76.952,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Temple free-food service on the 1st of each Malayalam month and on Sundays","food_source_contact":null,"food_distance_km":0.2,"nearest_river_name":"Killi","river_distance_km":0.3,"best_season_notes":"Feb–Mar for the Attukal Pongala, recognised by Guinness World Records as the largest annual gathering of women.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T20:39:31.59741+00:00","updated_at":"2026-11-04T12:15:35.665826+00:00","sthala_purana":"During the Pongala festival, millions of women cook a sweet rice offering (pongala) in the open on the streets around the temple in a single day — a scale of participation that led to its Guinness World Record listing.","etiquette_notes":null,"native_name":"ആറ്റുകാൽ ഭഗവതി ക്ഷേത്രം","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Thiruvananthapuram International Airport","nearest_airport_distance_km":3.7,"nearest_railway_station_name":"Thiruvananthapuram Central railway station","nearest_railway_distance_km":1.4,"emergency_contact_notes":null,"sthala_purana_source":null,"architecture_style":null,"construction_century":null},{"id":"887a528b-746f-48e6-8cb8-711377c14f41","name":"Angala Parameshwari Amman Temple, Putlur, Tiruvallur","deity":"Angala Parameswari (Devi)","sampradaya":"Shakta","significance":[],"country":"India","state":"Tamil Nadu","district":"Tiruvallur","town":"Putlur, Tiruvallur","latitude":13.1555,"longitude":79.931,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_s