ar","district":"Gaya","town":"Konch","latitude":24.9337,"longitude":84.7716,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Morhar River","river_distance_km":9.9,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:53.924452+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A brick Shiva temple at Konch in Gaya district, Bihar, enshrining a Shivalinga. Its tower has a curved nagara profile and is compared with the Mahabodhi temple, though its sides curve and it lacks niches. Mixed brick types suggest repeated repairs, and a panel of the Dashavataras of Vishnu lies inside.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Gaya International Airport","nearest_airport_distance_km":27.8,"nearest_railway_station_name":"Guraru railway station","nearest_railway_distance_km":13.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Koncheswar Mahadev), summarised; location via OpenStreetMap","architecture_style":"Nagara","construction_century":null},{"id":"8a5d1c1d-780c-4522-b992-ba84967d8448","name":"Lakshmi Narasimha Temple, Bhadravati","deity":"Vishnu as Lakshminarasimha","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Karnataka","district":"Shimoga","town":"Bhadravathi","latitude":13.84853,"longitude":75.70036,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Bhadra River","river_distance_km":0.4,"best_season_notes