unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Dayaa River","river_distance_km":3.4,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:59.639499+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A 10th-century Shiva temple in Bhubaneswar, dated to about 950-975 CE and important in the study of how Odisha's temples developed. Its style is seen as the high point of earlier developments and the start of a century of experiment that led to the Rajarani and Lingaraj temples. It is a prominent tourist attraction.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Biju Patnaik International Airport","nearest_airport_distance_km":3.1,"nearest_railway_station_name":"Bhubaneswar railway station","nearest_railway_distance_km":2.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Mukteshvara Temple, Bhubaneswar), summarised; location via OpenStreetMap","architecture_style":"Kalinga","construction_century":10},{"id":"8b75666b-2348-4612-b368-5b243317154e","name":"Danteshwari Temple, Dantewada","deity":"Danteshwari (Durga)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Chhattisgarh","district":"Dantewada","town":"Dantewada","latitude":18.9012,"longitude":81.345,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Sankini-Dankini (confluence)","river_distance_km":0.2,"best_season_notes":"Nov–Feb. The Dussehra celebrations here run for months by local Bastar tradition, unusually long.","submitted_by":null,"status":"approved","verified