am and Karthikai. The state endowments board runs it.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Open 6:30 am to 12 pm and 5 pm to 8:30 pm.","accessibility_notes":null,"nearest_airport_name":"Tiruchirapalli International Airport","nearest_airport_distance_km":75.1,"nearest_railway_station_name":"Karur Junction railway station","nearest_railway_distance_km":3.1,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Balasubramaniyaswamy Temple), summarised; location via OpenStreetMap","architecture_style":"Dravidian","construction_century":null},{"id":"9cd092d7-c6be-457f-a642-5a5f69ea046f","name":"Dhingu Mata Temple","deity":"Dhingu Mata","sampradaya":"Shakta","significance":[],"country":"India","state":"Himachal Pradesh","district":"Shimla","town":"Shanan","latitude":31.10553,"longitude":77.20026,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Ashmi River","river_distance_km":4.7,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:36.086063+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Dhingu Mata Temple sits on top of Dhingu Dhar hill above Sanjauli in Shimla, Himachal Pradesh. It is named after its founder, the local ruler Raja Dhingu, and is popular with locals and tourists.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Shimla Airport","nearest_airport_distance_km":12.9,"nearest_railway_station_name":"Shimla railway station","nearest_railway_distance_km":3.8,"emergency_contact_notes":null