74-f325f3d7be06","name":"EME Temple","deity":"Shiva as Dakshinamoorthy","sampradaya":"Shaiva","significance":[],"country":"India","state":"Gujarat","district":"Vadodara","town":"Vadodara","latitude":22.3314,"longitude":73.192,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Vishwamitri River","river_distance_km":0.6,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:03:52.882408+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A modern temple on the EME School campus in Vadodara, built in 1966 and run by the Indian Army. It honours Shiva as Dakshinamoorthy and includes a Navgraha shrine. Its design is inspired by a geodesic dome, and its open spaces hold 108 old stone statues of Hindu deities dated roughly 600 to 1600 CE.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Vadodara Green Airport Harni","nearest_airport_distance_km":3.6,"nearest_railway_station_name":"Vadodara Junction railway station","nearest_railway_distance_km":2.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (EME Temple), summarised; location via OpenStreetMap","architecture_style":"Geodesic dome inspired","construction_century":20},{"id":"a554ff9c-09ef-42a3-8855-bf3ddcddf6fa","name":"Jakhu Temple, Shimla","deity":"Hanuman","sampradaya":null,"significance":["108-ft Hanuman statue"],"country":"India","state":"Himachal Pradesh","district":"Shimla","town":"Shimla","latitude":31.10117,"longitude":77.18183,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Ashmi River","river_distance_km":4.9,"best_season_notes":"Tied historically to Shimla's Dussehra observances.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T08:39:44.697229+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Sited on Jakhu Hill, Shimla's highest point. Local legend, drawn from the Ramayana, holds that Hanuman rested here while searching for the Sanjeevani herb — legend, not historical record. The temple's actual founding date is not reliably documented; it is known to have been well established by the early 20th century (a 1912 postcard shows it standing). It is best known today for a 108-foot (33m) Hanuman statue, one of the tallest in the world, unveiled on 4 November 2010 and visible from much of Shimla.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Shimla Airport","nearest_airport_distance_km":11.1,"nearest_railway_station_name":"Shimla railway station","nearest_railway_distance_km":2.1,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia; local tradition","architecture_style":"Kath-Kuni-influenced hill-temple construction","construction_century":null},{"id":"a5faca1c-aa64-4010-a7b9-52e7ab1290c7","name":"Sarangapani Temple, Kumbakonam","deity":"Sarangapani (Vishnu)","sampradaya":"Vaishnava","significance":["Pancharanga Kshetram"],"country":"India","state":"Tamil Nadu","district":"Thanjavur","town":"Kumbakonam","latitude":10.95944,"longitude":79.37472,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Temple Annadanam served daily at 12:15pm","food_source_contact":null,"food_distance_km":0,"nearest_river_name":"Kaveri","river_distance_km":1,"best_season_notes":"Oct–Feb; the temple car festival (Panguni, Mar/Apr) is a major local event.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-05T10:54:38.493897+00:00","updated_at":"2026-11-04T12:15:35.665826+00:00","sthala_purana":"The largest Vishnu temple in Kumbakonam and one of the five Pancharanga Kshetrams on the Kaveri, and a Divya Desam. Its rajagopuram rises about 173 feet across eleven tiers — the third-tallest gopuram among all Divya Desams, after Srirangam and Srivilliputhur. Sarangapani is also counted among the Pancha Kshetras where Lakshmi is held to have been born as Bhargavi, daughter of the sage Bhrigu. The earliest inscriptions here date to the late Chola period, with major expansion under the Vijayanagara and Nayaka rulers.","etiquette_notes":null,"native_name":"சாரங்கபாணி கோயில்","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Thanjavur Air Force Station","nearest_airport_distance_km":39,"nearest_railway_station_name":"Kumbakonam railway station","nearest_railway_distance_km":1.8,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":"Dravidian (Chola, Vijayanagara, Nayaka)","construction_century":12},{"id":"a5faf8c1-20b6-4466-97e6-dd1714ed8ad7","name":"Siddha Vinayaka","deity":"Ganesha as Siddha Vinayaka","sampradaya":"Ganapatya","significance":[],"country":"India","state":"Odisha","district":"Ganjam","town":"Panchma","latitude":19.23231,"longitude":84.73795,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Bahuda River","river_distance_km":12.4,"best_season_notes":null,"submitted_by":nul